using System.Net.Http.Json;
using System.Text.Json;
using Xunit;

namespace UrlShortener.IntegrationTests;

public sealed class LinkUrlNormalizationTests
{
    [Fact]
    public async Task CreateLink_NormalizesSchemeAndHost_RemovesDefaultPortAndUtmParameters()
    {
        using var factory = new ApiFactory();
        using var client = factory.Client();

        var response = await CreateLink(client,
            "HTTPS://ExAmPlE.Com:443/path?utm_source=newsletter&keep=one&utm_campaign=spring#section");

        Assert.True(response.IsSuccessStatusCode);
        var destination = GetDestination(await response.Content.ReadAsStringAsync());
        Assert.Equal("https", destination.Scheme);
        Assert.Equal("example.com", destination.Host);
        Assert.Equal(-1, destination.Port);
        Assert.Equal("/path", destination.AbsolutePath);
        Assert.Equal("#section", destination.Fragment);
        Assert.Equal("keep=one", destination.Query.TrimStart('?'));
    }

    [Fact]
    public async Task CreateLink_PreservesNonDefaultPortAndUnrelatedQueryParameters()
    {
        using var factory = new ApiFactory();
        using var client = factory.Client();

        var response = await CreateLink(client,
            "HTTP://ExAmPlE.Com:8080/path?keep=one&utm_medium=email&other=two");

        Assert.True(response.IsSuccessStatusCode);
        var destination = GetDestination(await response.Content.ReadAsStringAsync());
        Assert.Equal("http", destination.Scheme);
        Assert.Equal("example.com", destination.Host);
        Assert.Equal(8080, destination.Port);
        Assert.Equal("keep=one&other=two", destination.Query.TrimStart('?'));
    }

    [Fact]
    public async Task CreateLink_RemovesDefaultHttpPortAndDoesNotLeaveEmptyQuery()
    {
        using var factory = new ApiFactory();
        using var client = factory.Client();

        var response = await CreateLink(client, "HTTP://ExAmPlE.Com:80/path?utm_source=test");

        Assert.True(response.IsSuccessStatusCode);
        var body = await response.Content.ReadAsStringAsync();
        var destination = GetDestination(body);
        Assert.Equal("http", destination.Scheme);
        Assert.Equal("example.com", destination.Host);
        Assert.Equal(-1, destination.Port);
        Assert.Equal("/path", destination.AbsolutePath);
        Assert.Empty(destination.Query);
        Assert.DoesNotContain("?", GetDestinationText(body));
    }

    private static Task<HttpResponseMessage> CreateLink(HttpClient client, string url) =>
        client.PostAsJsonAsync("/api/v1/links", new { url });

    private static Uri GetDestination(string responseBody) =>
        Uri.TryCreate(GetDestinationText(responseBody), UriKind.Absolute, out var uri)
            ? uri
            : throw new Xunit.Sdk.XunitException("The create-link response did not contain an absolute destination URL.");

    private static string GetDestinationText(string responseBody)
    {
        using var document = JsonDocument.Parse(responseBody);
        return FindDestination(document.RootElement)
            ?? throw new Xunit.Sdk.XunitException("The create-link response did not contain a destination URL.");
    }

    private static string? FindDestination(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.Object)
        {
            foreach (var property in element.EnumerateObject())
            {
                if (property.Value.ValueKind == JsonValueKind.String &&
                    Uri.TryCreate(property.Value.GetString(), UriKind.Absolute, out var uri) &&
                    uri.Host.Equals("example.com", StringComparison.OrdinalIgnoreCase))
                    return property.Value.GetString();

                var nested = FindDestination(property.Value);
                if (nested is not null) return nested;
            }
        }
        else if (element.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in element.EnumerateArray())
            {
                var nested = FindDestination(item);
                if (nested is not null) return nested;
            }
        }

        return null;
    }
}
